/* Explicit Year 11 mechanics scenario journeys. All practice is original exam-style work. */
(function(){'use strict';const C=window.PhysicsScenarioCourse,H=C.helpers;
const {esc,math:E,note:N,pair,steps:W,paper,reveal:R,svg,text,line,arrow,ball,number,check}=H;
const P=x=>'<p>'+x+'</p>';const table=ps=>'<table class="pf-marking"><thead><tr><th>Working and reasoning</th><th>Marks</th></tr></thead><tbody>'+ps.map(p=>'<tr><td>'+esc(p)+'</td><td>1</td></tr>').join('')+'</tbody></table>';
const practice=q=>P('<b>Original exam-style question · '+q.points.length+' marks.</b> '+q.q)+paper('Your diagram, reasoning and calculation')+R('Compare with the explained marking table',table(q.points));
function make(id,parent,title,shortTitle,subtitle){const s={id,parent,title,shortTitle,subtitle,pages:[],bank:[],practice:[],constants:'Use g = 9.80 m/s², SI units and the stated idealisations. Choose a positive direction; retain calculator guard digits.',chapters:[['Recognise','Identify the scenario and model'],['Build','Connect diagrams and relationships'],['Solve','Explain worked calculations'],['Practise','Guided, independent and transfer questions']]};s.add=(c,title,body,type='learn')=>s.pages.push({chapter:c,title,html:'<div class="pp-page">'+body+'</div>',type});s.mc=(q,o,a,explain)=>s.bank.push({q,o,a,explain});s.finish=()=>{if(s.pages.length<30)throw Error(id+' too short');s.summary=subtitle;s.focus={question:s.practice[0].q,points:s.practice[0].points,claim:'A model applies without checking its conditions.'};C.register(s);};return s;}
function vgraph(){const x=t=>100+80*t,y=v=>220-30*v;return svg('Velocity-time graph: positive and negative areas show forward and backward displacement',arrow(80,220,700,220,'#0b8774')+arrow(100,330,100,45,'#2a6bb2')+'<path d="M100 100L260 100L420 280L580 280" stroke="#c87518" stroke-width="4" fill="none"/><path d="M100 220V100H260L366.667 220Z" fill="#0b8774" opacity=".15"/><path d="M366.667 220L420 280H580V220Z" fill="#2a6bb2" opacity=".15"/>'+[0,2,4,6].map(t=>text(x(t),365,String(t),'#18374d','middle')).join('')+text(110,35,'velocity v (m/s)')+text(75,106,'+4','#18374d','end')+text(75,286,'−2','#18374d','end')+text(520,395,'time t (s)')+text(110,440,'0–2 s: +4 m/s; 2–4 s: linear change; 4–6 s: −2 m/s.'),475);}
function forces(applied=20,friction=5){return svg('Horizontal block free-body diagram with upward normal, downward weight, applied force right and friction left','<rect x="280" y="170" width="130" height="85" fill="#dcebf3" stroke="#18374d"/>'+arrow(345,170,345,70,'#0b8774')+arrow(345,255,345,345,'#c87518')+arrow(410,210,580,210,'#2a6bb2')+arrow(280,210,165,210,'#a15bb5')+text(365,95,'N ↑')+text(365,330,'mg ↓')+text(455,180,'F = '+applied+' N →')+text(80,180,'f = '+friction+' N ←')+text(70,420,'Arrows are forces on the block; horizontal and vertical sums differ.'),460);}
function slope(){return svg('Inclined-plane force model: weight down, normal perpendicular and friction along the slope',line(130,320,620,90)+line(130,320,620,320,'#9aadb9',true)+'<path d="M180 320A50 50 0 0 0 175.3 298.7" fill="none" stroke="#526d82" stroke-width="2"/>'+text(190,310,'θ')+'<rect x="305" y="185" width="90" height="65" transform="rotate(-25 350 220)" fill="#dcebf3" stroke="#18374d"/>'+arrow(350,220,350,340,'#c87518')+arrow(350,220,299,112,'#0b8774')+arrow(350,220,445,175,'#2a6bb2')+text(365,340,'mg ↓')+text(205,110,'N: perpendicular')+text(455,170,'friction uphill')+text(80,45,'For a block sliding down: friction acts up the plane')+text(100,400,'Down-slope component: mg sinθ')+text(100,435,'Into-plane component: mg cosθ'),475);}
function collision(){return svg('One-dimensional collision model with a positive axis and two masses before and after sticking',arrow(80,95,700,95,'#526d82')+text(85,65,'+ direction →')+'<rect x="120" y="170" width="110" height="60" fill="#dcebf3"/><rect x="390" y="170" width="140" height="60" fill="#e6f2e9"/>'+arrow(240,200,340,200,'#2a6bb2')+text(120,155,'m₁; u₁ →')+text(390,155,'m₂; u₂ = 0')+'<rect x="265" y="300" width="230" height="60" fill="#efe5d4"/>'+arrow(505,330,625,330,'#c87518')+text(285,340,'m₁ + m₂')+text(505,390,'shared final v')+text(80,440,'Momentum conservation applies to the chosen system and interval.'),480);}
function energy(){return svg('Energy budget diagram showing gravitational energy becoming kinetic and thermal energy',text(80,80,'Initial energy')+arrow(220,75,390,75,'#0b8774')+text(440,80,'Final kinetic energy')+arrow(300,95,300,230,'#c87518')+text(315,230,'thermal / other transfers')+text(90,350,'Track the whole energy budget; friction does not destroy energy.')+text(90,415,'Choose a reference height and state the system boundary.'),460);}
function liftDiagram(){return svg('Passenger free-body diagram, with normal upward and weight downward; acceleration is described separately','<rect x="160" y="80" width="260" height="275" fill="#edf4f8" stroke="#526d82"/>'+ball(290,165,22)+line(290,190,290,270)+line(290,220,245,245)+line(290,220,335,245)+line(290,270,250,320)+line(290,270,330,320)+arrow(290,135,290,65,'#0b8774')+arrow(360,190,360,320,'#c87518')+text(85,40,'Forces on passenger')+text(325,70,'N upward')+text(365,370,'mg downward')+text(455,140,'Use up positive:')+text(455,190,'N − mg = ma')+text(455,260,'a is not another')+text(455,300,'force arrow.')+text(80,420,'Determine a from velocity change; then predict the scale reading.'),460);}
function connectedDiagram(){return svg('Table block and hanging mass linked by a taut ideal rope and pulley','<path d="M100 240H500V395" stroke="#526d82" stroke-width="4" fill="none"/><rect x="225" y="170" width="115" height="65" fill="#dcebf3" stroke="#18374d"/>'+ball(510,210,18,'#e6eff7')+line(340,205,510,205)+line(525,210,525,285)+'<rect x="480" y="285" width="90" height="80" fill="#e6f2e9" stroke="#18374d"/>'+arrow(340,175,430,175,'#2a6bb2')+arrow(480,285,480,240,'#2a6bb2')+arrow(525,365,525,425,'#c87518')+text(150,130,'table block m₁')+text(350,155,'T →')+text(580,325,'m₂')+text(395,255,'T ↑')+text(575,415,'m₂g ↓')+text(85,50,'Choose table-right and hanging-down positive along their paths')+text(80,465,'Ideal rope: equal path-acceleration magnitudes, one tension.'),505);}
function impulseGraph(){return svg('Triangular net force pulse with peak 100 newtons and duration 0.200 seconds',arrow(100,320,690,320,'#0b8774')+arrow(100,320,100,45,'#2a6bb2')+'<path d="M150 320L390 90L630 320Z" fill="#e6f2e9" stroke="#c87518" stroke-width="4"/>'+text(110,35,'net force (N)')+text(390,70,'100 N','#18374d','middle')+text(150,360,'0','#18374d','middle')+text(630,360,'0.200 s','#18374d','middle')+text(300,250,'Impulse = triangular area')+text(80,425,'J = ½ × 100 × 0.200 = 10.0 N·s'),460);}
function reboundDiagram(){return svg('Rebound: incoming velocity positive towards the wall and outgoing velocity negative away from it','<rect x="600" y="75" width="30" height="270" fill="#cedbe4"/>'+ball(200,145,18)+arrow(225,145,500,145,'#0b8774')+text(230,115,'Before: u = +10.0 m/s')+ball(200,285,18)+arrow(500,285,225,285,'#2a6bb2')+text(230,330,'After: v = −8.00 m/s')+text(85,40,'Positive axis: towards the wall')+text(85,420,'Δv = final − initial = −8.00 − (+10.0) = −18.0 m/s'),465);}
function workAngle(){return svg('Force at 60 degrees to horizontal displacement with horizontal and vertical components',line(90,300,680,300)+'<rect x="200" y="220" width="100" height="75" fill="#dcebf3" stroke="#18374d"/>'+arrow(300,250,410,59,'#c87518')+arrow(300,250,410,250,'#0b8774')+line(410,250,410,59,'#2a6bb2',true)+text(400,105,'F = 40.0 N')+text(350,230,'60°')+text(330,280,'Fparallel = F cos60°')+arrow(190,355,590,355,'#0b8774')+text(290,395,'displacement s = 3.00 m →')+text(80,45,'Only the force component along displacement contributes work'),440);}
function rampEnergy(){return svg('Rough ramp geometry: vertical drop 3.00 metres versus path length 5.00 metres',line(150,110,430,320)+line(150,110,150,320,'#2a6bb2',true)+line(150,320,430,320,'#526d82',true)+ball(175,120,12)+arrow(350,260,290,215,'#c87518')+text(80,45,'Start from rest')+text(175,250,'height drop H = 3.00 m')+text(350,120,'path length s = 5.00 m')+text(455,220,'friction opposes sliding')+text(80,400,'Gravity term uses H; constant-friction transfer uses s.'),445);}
function positionDiagram(){return svg('Position-time graph with increasing, constant and decreasing position; slope indicates direction',arrow(100,340,700,340,'#0b8774')+arrow(100,340,100,45,'#2a6bb2')+'<path d="M100 290L260 170H420L580 230" stroke="#c87518" stroke-width="4" fill="none"/>'+text(110,35,'position x (m)')+text(70,296,'2','#18374d','end')+text(70,176,'8','#18374d','end')+text(70,236,'5','#18374d','end')+[0,2,4,6].map((t,i)=>text(100+80*t,380,String(t),'#18374d','middle')).join('')+text(550,415,'time t (s)')+text(110,460,'Rise → positive velocity. Flat → rest. Fall → negative velocity.'),495);}
function tangentDiagram(){const points=Array.from({length:81},(_,i)=>{const t=4*i/80;return(i?'L':'M')+(100+120*t)+' '+(330-16*t*t)}).join(' ');return svg('Curved position-time graph with a tangent at two seconds and a labelled gradient triangle',arrow(100,330,690,330,'#0b8774')+arrow(100,330,100,40,'#2a6bb2')+'<path d="'+points+'" fill="none" stroke="#c87518" stroke-width="4"/>'+line(250,314,430,218,'#2a6bb2')+ball(340,266,7)+line(280,298,400,298,'#0b8774',true)+line(400,298,400,234,'#0b8774',true)+text(110,35,'position x = t² (SI units)')+text(435,200,'tangent at t = 2.00 s')+text(110,390,'Tangent points: (1.50 s, 2.00 m), (2.50 s, 6.00 m)')+text(110,435,'The tangent points are not two points on the curved trajectory.'),475);}
function accelGraph(){return svg('Acceleration-time stages: positive acceleration, zero acceleration, then negative acceleration',arrow(100,240,690,240,'#0b8774')+arrow(100,340,100,50,'#2a6bb2')+'<path d="M100 120H300M300 240H400M400 300H600" stroke="#c87518" stroke-width="5" fill="none"/>'+text(110,35,'acceleration a (m/s²)')+text(75,126,'+2','#18374d','end')+text(75,306,'−1','#18374d','end')+[0,2,3,5].map(t=>text(100+100*t,385,String(t),'#18374d','middle')).join('')+text(550,425,'time t (s)')+text(110,460,'Area gives Δv; initial velocity is still needed to find v.'),495);}
function linkedVelocity(){return svg('Velocity graph reconstructed from the piecewise position graph: plus three, zero, then minus one point five metres per second',arrow(100,220,690,220,'#0b8774')+arrow(100,340,100,45,'#2a6bb2')+'<path d="M100 100H260M260 220H420M420 280H580" stroke="#c87518" stroke-width="5" fill="none"/>'+text(110,35,'velocity (m/s)')+text(75,106,'+3','#18374d','end')+text(75,286,'−1.5','#18374d','end')+[0,2,4,6].map(t=>text(100+80*t,375,String(t),'#18374d','middle')).join('')+text(545,415,'time (s)')+text(110,455,'Velocity is the gradient of each position segment.'),490);}
function linkedStageVelocity(){return svg('Velocity reconstructed from the worked acceleration stages, starting at one metre per second',arrow(100,320,690,320,'#0b8774')+arrow(100,320,100,45,'#2a6bb2')+'<path d="M100 280L300 120H400L600 200" stroke="#c87518" stroke-width="4" fill="none"/>'+text(110,35,'velocity (m/s)')+text(75,286,'1','#18374d','end')+text(75,126,'5','#18374d','end')+text(75,206,'3','#18374d','end')+[0,2,3,5].map(t=>text(100+100*t,370,String(t),'#18374d','middle')).join('')+text(545,410,'time (s)')+text(110,455,'Velocity areas: 6.00 m + 5.00 m + 8.00 m = 19.0 m.'),490);}
function linkedPosition(){const path=Array.from({length:101},(_,i)=>{const t=i/20;let x=t<=2?t+t*t:t<=3?6+5*(t-2):11+5*(t-3)-.5*(t-3)**2;return(i?'L':'M')+(100+100*t)+' '+(380-14*x);}).join(' ');return svg('Position reconstructed from acceleration stages with initial position zero',arrow(100,380,690,380,'#0b8774')+arrow(100,380,100,50,'#2a6bb2')+'<path d="'+path+'" stroke="#c87518" stroke-width="4" fill="none"/>'+text(110,35,'position (m); xinitial = 0')+[0,2,3,5].map(t=>text(100+100*t,420,String(t),'#18374d','middle')).join('')+text(565,465,'time (s)')+text(75,302,'6','#18374d','end')+text(75,232,'11','#18374d','end')+text(75,120,'19','#18374d','end')+text(180,100,'Positive slopes throughout: no direction reversal.'),505);}
function energyBars(title,entries,unit='J'){const max=Math.max(...entries.map(e=>e[1]));return svg(title,text(75,35,title)+entries.map(([label,v],i)=>{const y=95+i*90;return text(75,y+23,label)+'<rect x="250" y="'+y+'" width="'+(400*v/max)+'" height="32" fill="'+['#2a6bb2','#0b8774','#c87518'][i%3]+'" rx="4"/>'+text(270+400*v/max,y+24,Number(v.toPrecision(5))+' '+unit);}).join('')+text(75,415,unit==='W'?'Bars share one scale: compare energy-transfer rates.':'Bars share one scale: compare energy amounts.'),450);}
function movingReleaseDiagram(){return svg('Moving separation: initially three kilograms at plus two metres per second, then two parts moving right',text(90,45,'Before: 3.00 kg at +2.00 m/s')+'<rect x="265" y="90" width="180" height="55" fill="#efe5d4"/>'+arrow(455,115,610,115,'#c87518')+'<rect x="150" y="245" width="140" height="65" fill="#dcebf3"/><rect x="450" y="245" width="100" height="65" fill="#e6f2e9"/>'+arrow(165,350,215,350,'#2a6bb2')+arrow(450,350,685,350,'#0b8774')+text(110,215,'2.00 kg; v = +0.500 m/s')+text(415,215,'1.00 kg; v = +5.00 m/s')+text(90,425,'Both move right in this frame; total momentum remains +6.00 kg·m/s.'),470);}
// Position-time graphs: displacement, average and instantaneous velocity.
{
const s=make('y11-motion-graphs-focus-1','y11-motion-graphs','Position graphs: direction, tangents and average motion','Position-time graphs','Distinguish an object’s position from the distance it travels and use local gradients.'),A=s.add;
A(0,'A graph records positions, not a road shape',positionDiagram()+P('The vertical coordinate tells where the object is relative to an origin at each time. A descending graph means position decreases; it does not show a downhill road.'));
A(0,'Specify the origin and positive axis',P('A position of −2 m means two metres on the negative side of the chosen origin. The object can be moving towards or away from that origin; its position sign alone does not give motion direction.'));
A(0,'Position and displacement are different readings',E('Δx = xfinal − xinitial')+P('An interval from +2 m to +8 m gives +6 m displacement. Final position is +8 m. The distinction matters when a graph does not start at zero.'));
A(0,'A flat segment shows a stationary interval',P('When x is constant while time advances, its gradient is zero and velocity is zero. A nonzero position on that flat segment does not imply motion.'));
A(0,'Graph direction comes from gradient',pair('<h3>Positive gradient</h3>'+P('Position increases: velocity points along the positive axis.'),'<h3>Negative gradient</h3>'+P('Position decreases: velocity points along the negative axis.')));
A(0,'Speed is the magnitude of the gradient',P('Compare the absolute slopes to compare speeds. A steeper negative gradient can represent faster travel than a shallow positive gradient. Do not compare only whether the plotted positions are larger.'));
A(0,'A return does not erase distance travelled',P('A journey can end at its initial position with zero net displacement. Add the path lengths of its separate direction intervals for distance.'));
A(1,'Straight-line velocity',E('v = (x₂ − x₁)/(t₂ − t₁)')+P('For a straight segment, the gradient is the same across the segment, so average and instantaneous velocity there agree. Choose points from that segment, not across a corner.'));
A(1,'Average velocity across an interval',E('vaverage = total displacement / total elapsed time')+P('A secant joining the interval endpoints gives average velocity even if the object rests or reverses between those endpoints.'));
A(1,'Average speed counts the whole path',E('Average speed = total distance / total elapsed time')+P('Include stationary time when calculating an average for the entire trip. Do not average stage speeds arithmetically unless the relevant time weighting supports it.'));
A(1,'A curve has a changing velocity',tangentDiagram()+P('A tangent touches the curve locally. Its gradient estimates instantaneous velocity at the chosen time; a long secant instead describes an interval average.'));
A(1,'Construct a large tangent triangle',P('Use two separated points on the drawn tangent line. They need not be points on the data curve. A larger readable triangle reduces the relative effect of small coordinate-reading errors.'));
A(1,'The slope’s units reveal the quantity',E('Position units / time units = m/s')+P('A position-time slope gives velocity, not acceleration. Acceleration concerns how this velocity changes over time.'));
A(1,'Corners describe a change of velocity',P('A piecewise line can represent a simplified sudden transition between stage velocities. Real changes take finite time. Do not claim a corner proves literally instantaneous acceleration.'));
A(2,'Worked graph: read the stages',positionDiagram()+P('The object moves from x = 2 m to 8 m during 0–2 s, rests until 4 s, and moves to 5 m by 6 s. Find each stage velocity and whole-trip averages.'),'worked');
A(2,'Worked graph: each velocity',E('v₁ = (8 − 2)/2 = +3 m/s<br>v₂ = 0 m/s<br>v₃ = (5 − 8)/2 = −1.5 m/s')+P('The third stage is negative because position decreases, although both its endpoint positions are positive.'),'worked');
A(2,'Worked graph: net displacement and distance',E('Net displacement = 5 − 2 = +3 m<br>Distance = |8 − 2| + 0 + |5 − 8| = 9 m')+P('The same graph supplies both quantities, but their definitions differ.'),'worked');
A(2,'Worked graph: the two averages',E('Average velocity = 3/6 = +0.50 m/s<br>Average speed = 9/6 = 1.50 m/s')+P('Both include the two-second stop because the requested interval is the full six-second trip.'),'worked');
A(2,'Worked straight relation',P('A moving object follows x = −4.00 + 2.50t, with metres and seconds.')+E('Initial position = −4.00 m; velocity = +2.50 m/s<br>x(3.00) = +3.50 m')+P('The object begins on the negative side but moves positively. Crossing the origin at 1.60 s does not make it stop.'),'worked');
A(2,'Worked curve: instantaneous velocity',tangentDiagram()+E('At t = 2.00 s, tangent gradient = (6.00 − 2.00)/(2.50 − 1.50)<br>vinstantaneous = +4.00 m/s')+P('The tangent points describe the line used for the local estimate, not two actual positions reached on the curve.'),'worked');
A(2,'Worked curve: compare a secant',E('For x = t², x(1) = 1 m and x(4) = 16 m<br>vaverage = (16 − 1)/(4 − 1) = 5 m/s')+P('This average over 1–4 s does not equal the instantaneous velocity at 2 s. Specify the interval or instant in the answer.'),'worked');
A(3,'Guided: a negative gradient',number('pos-negative','Position falls from +7 m to +1 m over 3 s. Find velocity.',-2,'m/s','v = (1 − 7)/3 = −2 m/s.',.01),'practice');
A(3,'Guided: a return trip',P('A walker goes 12 m out and 12 m back in 8 s.')+number('pos-avg','Average velocity',0,'m/s','Net displacement is zero, so average velocity is zero.')+number('pos-speed','Average speed',3,'m/s','Distance = 24 m; average speed = 24/8 = 3 m/s.',.01),'practice');
A(3,'Guided: tangent points',number('tangent','A tangent passes through (2 s, 3 m) and (5 s, 15 m). Find instantaneous velocity at its contact point.',4,'m/s','Tangent gradient = (15 − 3)/(5 − 2) = 4 m/s.',.01),'practice');
const q1={q:'An object is at x = −3.00 m at t = 0, moves linearly to x = +5.00 m at 2.00 s, rests to 3.00 s, then moves linearly to x = +1.00 m at 5.00 s. Find stage velocities, distance, displacement and both whole-trip averages.',points:['Stage velocities are +4.00 m/s, 0 and −2.00 m/s.','Net displacement = 1.00 − (−3.00) = +4.00 m.','Total distance = 8.00 + 4.00 = 12.0 m.','Average velocity = +4.00/5.00 = +0.800 m/s.','Average speed = 12.0/5.00 = 2.40 m/s, including the stationary interval.']};
const q2={q:'At t = 3.00 s on a curved position-time graph, a tangent passes through (2.00 s, 4.00 m) and (4.00 s, 16.0 m). Actual graph endpoints over 1.00–5.00 s are 1.00 m and 25.0 m. Find the instantaneous and interval-average velocities and explain why equality here does not make them the same measurement.',points:['Instantaneous velocity is tangent gradient = (16.0 − 4.00)/(4.00 − 2.00) = 6.00 m/s.','Average velocity over 1–5 s = (25.0 − 1.00)/(5.00 − 1.00) = 6.00 m/s.','A tangent represents a local instant; a secant represents the chosen interval.','Their equal numerical values in this particular example do not mean they are generally equal.']};s.practice=[q1,q2];
A(3,'Independent: direction stages and averages',practice(q1),'practice');A(3,'Independent: tangent versus secant',practice(q2),'practice');
A(3,'Use position measurements to estimate motion',P('Plot positions at known times, include uncertainty where given, and fit the trend. A noisy dot-to-dot line can create artificial rapid velocity changes. Choose a method appropriate to the underlying motion.'));
A(3,'A horizontal origin crossing is not a reversal',P('Direction reverses when gradient changes sign. A rising straight line can cross x = 0 while its velocity remains positive and unchanged.'));
A(3,'Choose the largest speed correctly',P('Inspect slope magnitude within each segment or tangent. The highest point on a position graph is a largest position, not necessarily a largest speed.'));
A(3,'Time-weighted motion averages',E('Δx = Σ(vstage Δtstage)')+P('When stage durations differ, sum their displacements then divide by total time. Simply averaging the listed velocities ignores how long each acted.'));
A(3,'Connect the position graph to a velocity graph',linkedVelocity()+P('Draw a velocity-time graph with a constant value for each straight position segment and zero for each flat segment. A smoothly curving position graph needs a continuously changing velocity rather than a copied curve shape.'));
A(3,'Your position-graph reference',E('Read x → calculate signed changes → use gradients → distinguish tangent from secant')+P('Calculate distance using direction stages and use full elapsed time for whole-trip averages.'));
s.mc('A negative position means…',['motion must be negative','the object is on the negative side of the origin','negative distance travelled'],1,'Position sign identifies location, not velocity.');s.mc('A tangent gradient gives…',['instantaneous velocity','total distance','initial force'],0,'It describes the local position change rate.');s.mc('Average speed uses…',['net displacement','total distance','final position alone'],1,'Count the entire travelled path.');s.mc('Rest on a position-time graph appears as…',['a flat interval','a steep negative line','the origin only'],0,'Position is unchanged over time.');s.mc('A slope triangle should use…',['points on the tangent or fitted line being measured','any two nearby dots','only zero coordinates'],0,'Choose points belonging to the relevant line.');s.mc('A reversal requires…',['crossing position zero','velocity changing sign','a negative position'],1,'Gradient direction must change.');s.finish();
}
// Acceleration-time graph integration and linked motion representations.
{
const s=make('y11-motion-graphs-focus-3','y11-motion-graphs','Acceleration graphs: building velocity and position','Linked motion graphs','Use signed acceleration areas and carry initial conditions through multiple stages.'),A=s.add;
A(0,'An acceleration graph does not show velocity directly',accelGraph()+P('An object can have negative acceleration while moving positively or negatively. To know velocity, you need its starting velocity and accumulated change.'));
A(0,'Separate acceleration from displacement',P('A vertical graph value in m/s² is not a position or speed. Read axes before using the shape. Acceleration describes how quickly signed velocity changes.'));
A(0,'Zero acceleration preserves the existing velocity',P('It does not necessarily stop the object. During a zero-acceleration stage, the velocity stays at the value reached at that stage’s start.'));
A(0,'Positive acceleration can slow negative motion',P('If u is negative, positive acceleration first makes velocity less negative. The object may stop, then begin moving positively if acceleration continues.'));
A(0,'Initial velocity is essential',P('Two objects with the same acceleration-time history but different u have the same Δv but different final velocities and displacements. A graph area alone cannot choose u.'));
A(0,'Choose one clock for the whole journey',P('Use the absolute graph time to identify stages, but use each stage duration in its motion calculation. Repeating a stage’s end time as its duration double-counts elapsed time.'));
A(0,'Why areas have velocity units',E('(m/s²) × s = m/s')+P('Area under acceleration versus time gives a velocity change. Adding initial velocity gives the velocity itself.'));
A(1,'Integrate a rectangular acceleration segment',E('Δv = aΔt')+P('A horizontal segment’s signed area is its height times duration. Below-axis segments subtract from velocity, not necessarily from speed.'));
A(1,'Triangle and trapezium areas',E('Triangle: Δv = ½apeak Δt<br>Linear ramp: Δv = ½(a₁ + a₂)Δt')+P('These areas give velocity change even when acceleration is not constant. Constant-acceleration displacement equations cannot automatically be used over that entire ramp.'));
A(1,'Carry the stage endpoint forward',E('ustage 2 = vstage 1')+P('Every stage begins with the velocity reached previously. This is the bridge between the separate calculations.'));
A(1,'Construct the velocity graph',P('Constant acceleration gives a straight velocity segment. Zero acceleration gives a horizontal velocity segment. A linear acceleration ramp gives a curved velocity graph.'));
A(1,'Then use velocity-time area for displacement',E('s = area under the reconstructed velocity graph')+P('For piecewise constant acceleration, each velocity segment is straight and a trapezium area works. Do not use acceleration-time area as displacement.'));
A(1,'Displacement requires its own starting point',E('xfinal = xinitial + Σsstage')+P('Total stage displacement does not automatically equal final position. Add the stated initial position after calculating the motion.'));
A(1,'Split a velocity reversal for total distance',P('Locate where v becomes zero inside a stage. Compute forward and backward path lengths separately and add their positive magnitudes. Net signed area gives displacement instead.'));
A(2,'Worked acceleration journey: identify stages',accelGraph()+P('Initial velocity is +1.00 m/s. Acceleration is +2.00 m/s² for 0–2 s, zero for 2–3 s and −1.00 m/s² for 3–5 s. Find velocities and displacement.'),'worked');
A(2,'Worked first stage: area and displacement',E('Δv₁ = 2.00(2.00) = +4.00 m/s<br>v(2) = 1.00 + 4.00 = 5.00 m/s<br>s₁ = ½(1.00 + 5.00)(2.00) = 6.00 m')+P('Initial velocity supplies the lower edge of the velocity trapezium.'),'worked');
A(2,'Worked second stage: zero a is not zero v',E('Δv₂ = 0; v(3) = 5.00 m/s<br>s₂ = 5.00(1.00) = 5.00 m')+P('The duration is 3 − 2 = 1 s. The object keeps moving during this stage.'),'worked');
A(2,'Worked final stage',E('Δv₃ = −1.00(2.00) = −2.00 m/s<br>v(5) = 3.00 m/s<br>s₃ = ½(5.00 + 3.00)(2.00) = 8.00 m')+P('Velocity remains positive throughout this stage, so no distance/displacement sign split is needed.'),'worked');
A(2,'Worked totals and a check',linkedStageVelocity()+E('Total Δv = +4.00 + 0 − 2.00 = +2.00 m/s<br>Final v = 1.00 + 2.00 = 3.00 m/s<br>Total displacement = 6.00 + 5.00 + 8.00 = 19.0 m')+P('Acceleration areas check the final velocity. The separate velocity areas check displacement.'),'worked');
A(2,'Worked reversal under a constant stage',P('An object begins at −4.00 m/s and experiences +2.00 m/s² for 3.00 s.')+E('vfinal = −4.00 + 2.00(3.00) = +2.00 m/s<br>tturn = 2.00 s<br>s = −4.00(3.00) + ½(2.00)(3.00)² = −3.00 m')+P('It travels 4.00 m negatively before turning and 1.00 m positively after: total distance 5.00 m.'),'worked');
A(2,'Worked changing acceleration pulse',P('Acceleration rises linearly from 0 to +4.00 m/s² in 2.00 s.')+E('Δv = ½(2.00)(4.00) = +4.00 m/s')+P('This gives the velocity change. Using constant a = 4 throughout would double it; using constant-acceleration displacement equations across the ramp would require justification.'),'worked');
A(3,'Guided: an acceleration rectangle',number('a-area','a = −3.00 m/s² for 2.00 s. Find Δv.',-6,'m/s','Signed area = −3.00 × 2.00 = −6.00 m/s.',.01),'practice');
A(3,'Guided: include initial velocity',number('a-vfinal','For u = +10.0 m/s and Δv = −6.00 m/s, find vfinal.',4,'m/s','vfinal = u + Δv = 10.0 − 6.00 = +4.00 m/s.',.01),'practice');
A(3,'Guided: a zero-acceleration interval',number('a-rest','An object enters a 3.00 s zero-acceleration interval at −2.00 m/s. Find displacement.',-6,'m','Velocity stays −2.00 m/s; s = −2.00 × 3.00 = −6.00 m.',.01),'practice');
const q1={q:'A cart starts at +2.00 m/s. Its acceleration is +3.00 m/s² for 2.00 s, zero for 1.00 s and −2.00 m/s² for 2.00 s. Calculate each endpoint velocity and total displacement.',points:['After first stage v = 2.00 + 3.00 × 2.00 = 8.00 m/s; s₁ = 10.0 m.','After zero-a stage v = 8.00 m/s; s₂ = 8.00 m.','Final v = 8.00 − 2.00 × 2.00 = 4.00 m/s; s₃ = 12.0 m.','Total displacement = 10.0 + 8.00 + 12.0 = +30.0 m.','Each stage duration and starting velocity must be carried correctly.']};
const q2={q:'Acceleration changes linearly from −2.00 to +4.00 m/s² over 3.00 s. Initial velocity is +5.00 m/s. Find velocity change and final velocity, and explain why a constant-acceleration displacement formula is not directly justified.',points:['Signed trapezium area = ½(−2.00 + 4.00)(3.00) = +3.00 m/s.','Final velocity = 5.00 + 3.00 = +8.00 m/s.','The acceleration varies continuously over the interval.','The area gives Δv, but a displacement calculation needs the corresponding velocity history rather than an assumed constant endpoint acceleration.']};s.practice=[q1,q2];
A(3,'Independent: linked constant-a stages',practice(q1),'practice');A(3,'Independent: a changing-acceleration area',practice(q2),'practice');
A(3,'Final speed needs the sign check',P('A final velocity of −8 m/s means speed 8 m/s. An acceleration area can produce a signed change without telling whether speed grew or shrank; compare the initial and final velocity magnitudes.'));
A(3,'Graph intercepts carry different initial conditions',P('A velocity intercept gives u; a position intercept gives xinitial. An acceleration intercept describes acceleration at that instant, not either of those starting quantities.'));
A(3,'A whole-trip average acceleration is not the whole history',E('aaverage = Δvtotal/Δttotal')+P('It reproduces the endpoint velocity change. Different acceleration histories with that average can have different displacements.'));
A(3,'Qualitative position curvature',linkedPosition()+P('Increasing velocity corresponds to upward curvature in a position-time graph; decreasing velocity corresponds to downward curvature. The current slope still decides travel direction, so upward curvature does not guarantee positive velocity.'));
A(3,'Check a multistage solution using units',P('Acceleration areas should end in m/s, velocity areas in m. If an intermediate expression for displacement contains m/s, one integration or time factor is missing.'));
A(3,'Your linked-graph reference',E('a area → Δv → add u → construct v history → v area → displacement → add xinitial')+P('Carry stage conditions and distinguish endpoint quantities from changes.'));
s.mc('Acceleration-time area gives…',['displacement','velocity change','final velocity without u'],1,'Initial velocity must still be added.');s.mc('Zero acceleration means…',['zero velocity','velocity stays at its existing value','zero position'],1,'No velocity change occurs.');s.mc('A linear acceleration ramp gives a velocity graph that is…',['curved','always horizontal','a copy of the a graph'],0,'Its slope changes continuously.');s.mc('To reconstruct position you also need…',['initial position','mass always','a negative time'],0,'Displacement is added to xinitial.');s.mc('A negative acceleration while v is negative initially…',['increases speed','decreases speed','stops motion instantly'],0,'It acts in the same direction as velocity.');s.mc('Average acceleration fixes…',['all intermediate positions','net velocity change over the interval','total distance uniquely'],1,'The detailed time history still matters for displacement.');s.finish();
}
function elasticDiagram(){return svg('Elastic collision after-state: two kilogram cart at plus one metre per second and one kilogram cart at plus four metres per second','<rect x="115" y="130" width="180" height="70" fill="#dcebf3" stroke="#18374d"/><rect x="450" y="130" width="110" height="70" fill="#e6f2e9" stroke="#18374d"/>'+arrow(170,250,245,250,'#2a6bb2')+arrow(430,250,680,250,'#0b8774')+text(110,100,'m₁ = 2.00 kg')+text(445,100,'m₂ = 1.00 kg')+text(110,300,'v₁ = +1.00 m/s')+text(435,300,'v₂ = +4.00 m/s')+text(90,40,'After an ideal elastic collision; arrows indicate velocities')+text(90,395,'Before: u₁ = +3.00 m/s; u₂ = 0. Axis is right-positive.'),440);}
function recoilDiagram(){return svg('Explosion from rest: two fragments depart in opposite directions and their momenta cancel','<rect x="125" y="155" width="145" height="70" fill="#dcebf3" stroke="#18374d"/><rect x="440" y="155" width="200" height="70" fill="#e6f2e9" stroke="#18374d"/>'+arrow(285,275,85,275,'#2a6bb2')+arrow(420,275,685,275,'#0b8774')+text(100,125,'mleft = 3.00 kg')+text(440,125,'mright = 2.00 kg')+text(90,320,'vleft = −4.00 m/s')+text(435,320,'vright = +6.00 m/s')+text(90,45,'Initially combined and at rest; choose right positive')+text(90,410,'pleft = −12.0; pright = +12.0 kg·m/s. Total remains zero.'),455);}
// Elasticity: calculate momentum and kinetic energy as separate conserved quantities.
{
const s=make('y11-collisions-focus-2','y11-collisions','Collisions: elastic, inelastic and separating objects','Elasticity & separation','Use both momentum and kinetic-energy evidence to classify and solve collisions.'),A=s.add;
A(0,'A collision can conserve momentum but lose kinetic energy',P('Two carts can emerge separately or stick. With negligible external impulse, system momentum is conserved in either case. Kinetic energy distinguishes ideal elastic from inelastic behaviour.'));
A(0,'Define elastic precisely',E('Elastic: ΣEₖ before = ΣEₖ after')+P('This is an ideal condition for the chosen collision. Real objects may transfer some energy into sound, deformation and internal heating, even when a rebound looks springy.'));
A(0,'Inelastic does not mean no rebound',P('Objects can rebound and still lose total kinetic energy. “Perfectly inelastic” refers to sticking with a shared final velocity, not to every inelastic collision.'));
A(0,'Choose the two-object system',P('Internal collision forces exchange momentum between the objects. Conservation of the system total requires the external impulse to be negligible over the interval, not that each object experiences no force.'));
A(0,'Write four signed velocities',E('Before: u₁, u₂; after: v₁, v₂')+P('Use one positive axis across both states. Kinetic energy uses squared velocities, but momentum must keep their signs.'));
A(0,'Two unknown velocities need two conditions',P('Momentum alone is one scalar equation for a one-dimensional two-object collision. For an ideal elastic event, kinetic-energy conservation supplies a second equation. A measured final velocity can instead supply enough information.'));
A(0,'A stationary target is only a special case',collision()+P('For head-on motion, both initial velocities can be nonzero with opposite signs. Do not insert u₂ = 0 unless the problem actually says the target is initially stationary.'));
A(1,'Momentum equation',E('m₁u₁ + m₂u₂ = m₁v₁ + m₂v₂')+P('The left and right sides represent total system momentum, not separate conservation for each object.'));
A(1,'Elastic-energy equation',E('½m₁u₁² + ½m₂u₂² = ½m₁v₁² + ½m₂v₂²')+P('The shared factor ½ can be cancelled when solving, but preserve the squared terms and both masses.'));
A(1,'An equal-mass elastic shortcut',P('For an ideal one-dimensional elastic collision of equal masses, the physically interacting solution exchanges their velocities: v₁ = u₂ and v₂ = u₁. Check both conservation equations to justify it.'));
A(1,'Unequal masses do not exchange velocities generally',P('The lighter and heavier objects can have different changes. Use the two equations or a correctly derived relation rather than importing the equal-mass shortcut.'));
A(1,'Derive the relative-velocity condition',E('For a nontrivial 1D elastic collision: u₁ − u₂ = −(v₁ − v₂)')+P('This follows by factoring the squared velocity differences in the energy equation and combining with momentum. The relative approach velocity reverses into relative separation velocity.'));
A(1,'Use the derived condition as the second equation',P('It can simplify algebra for an ideal elastic 1D event. It is not an extra universally conserved quantity for inelastic collisions; keep the elastic assumption attached.'));
A(1,'Evaluate kinetic-energy loss for a measured collision',E('Loss of macroscopic Eₖ = Eₖ before − Eₖ after')+P('A positive loss indicates transfer to other energy forms. If Eₖ increases, stored energy may be released or the measurements/model need investigation.'));
A(2,'Worked unequal masses: define the event',P('A 2.00 kg cart at +3.00 m/s hits a stationary 1.00 kg cart. The ideal collision is elastic. Find both final velocities.')+E('Momentum: 6.00 = 2.00v₁ + 1.00v₂'),'worked');
A(2,'Worked elastic event: use relative separation',E('3.00 − 0 = −(v₁ − v₂)<br>v₂ = v₁ + 3.00')+P('Combine this with momentum rather than assuming a shared velocity, because the carts separate.'),'worked');
A(2,'Worked elastic event: solve',E('6.00 = 2.00v₁ + v₁ + 3.00<br>v₁ = +1.00 m/s; v₂ = +4.00 m/s')+elasticDiagram()+P('Both move positively, but the lighter target moves faster than the incident cart’s original speed. That is consistent with the total energy budget.'),'worked');
A(2,'Worked elastic event: check energy',E('Eₖ before = ½(2.00)(3.00)² = 9.00 J<br>Eₖ after = ½(2.00)(1.00)² + ½(1.00)(4.00)² = 9.00 J')+P('Momentum also checks: 2.00(1.00) + 1.00(4.00) = 6.00 kg·m/s.'),'worked');
A(2,'Worked equal masses: opposite approach',P('Equal 1.00 kg carts approach at +4.00 and −2.00 m/s in an ideal elastic collision.')+E('v₁ = −2.00 m/s; v₂ = +4.00 m/s')+P('Total momentum is +2.00 kg·m/s before and after; total kinetic energy is 10.0 J before and after. The first cart reverses.'),'worked');
A(2,'Worked heavy stationary target',P('A 1.00 kg cart at +4.00 m/s collides elastically with a stationary 3.00 kg cart.')+E('Momentum: 4.00 = v₁ + 3.00v₂<br>Relative condition: v₂ = v₁ + 4.00<br>v₁ = −2.00 m/s; v₂ = +2.00 m/s')+P('The light cart rebounds. The heavier target still moves and carries +6.00 kg·m/s momentum.'),'worked');
A(2,'Worked measured separation: classify it',energyBars('Measured collision: kinetic-energy accounting',[['Before',8],['After',2],['Transferred',6]])+P('A 1.00 kg cart begins at +4.00 m/s and a 3.00 kg target at rest. After a measured collision, v₁ = +1.00 m/s and v₂ = +1.00 m/s.')+E('Momentum before = 4.00; after = 1.00 + 3.00 = 4.00 kg·m/s<br>Eₖ before = 8.00 J; after = 2.00 J')+P('Momentum agrees, but kinetic energy drops by 6.00 J. The event is inelastic; these shared final velocities are consistent with sticking if that is observed.'),'worked');
A(3,'Guided: equal masses with one at rest',P('Equal masses collide ideally elastically: u₁ = +5.00 m/s and u₂ = 0.')+number('equal-v1','Final velocity of incident object',0,'m/s','Equal-mass 1D elastic velocities exchange: v₁ = 0.')+number('equal-v2','Final velocity of target',5,'m/s','v₂ = u₁ = +5.00 m/s.',.01),'practice');
A(3,'Guided: test a proposed result',P('For the worked 2 kg/1 kg elastic case, someone proposes v₁ = 2 m/s and v₂ = 2 m/s.')+paper('Check momentum and energy separately')+R('Reasoning',P('Momentum is 6 kg·m/s and therefore agrees. Final energy is 6 J rather than 9 J, so the result is not the stated elastic event.')),'practice');
A(3,'Guided: relative velocity after elastic contact',number('rel-elastic','u₁ = +7 m/s and u₂ = +2 m/s. Find v₁ − v₂ for a 1D elastic collision.',-5,'m/s','The relative velocity reverses: v₁ − v₂ = −(7 − 2) = −5 m/s.',.01),'practice');
const q1={q:'A 1.00 kg cart at +6.00 m/s hits a stationary 2.00 kg cart in an ideal elastic 1D collision. Find final velocities and verify momentum and kinetic energy.',points:['Momentum: 6.00 = v₁ + 2.00v₂.','Elastic relative condition: v₂ = v₁ + 6.00.','Solve v₁ = −2.00 m/s and v₂ = +4.00 m/s.','Momentum after = −2.00 + 8.00 = +6.00 kg·m/s.','Energy before = 18.0 J; after = 2.00 + 16.0 = 18.0 J.']};
const q2={q:'A 2.00 kg cart at +5.00 m/s hits a stationary 3.00 kg cart. After contact its measured velocity is +2.00 m/s. Use negligible external impulse to find the target velocity, then determine whether the collision was elastic.',points:['Initial momentum = 2.00 × 5.00 = 10.0 kg·m/s.','10.0 = 2.00(2.00) + 3.00v₂ gives v₂ = +2.00 m/s.','Initial kinetic energy = 25.0 J.','Final kinetic energy = ½(2.00 + 3.00)(2.00)² = 10.0 J.','The collision is inelastic; 15.0 J leaves macroscopic kinetic energy.']};s.practice=[q1,q2];
A(3,'Independent: ideal elastic rebound',practice(q1),'practice');A(3,'Independent: a measured collision',practice(q2),'practice');
A(3,'A wall is a different system choice',P('For a ball-plus-wall system, the wall and Earth may carry tiny velocities but significant momentum. Treating the ball alone as momentum-conserving during its wall contact is incorrect.'));
A(3,'Two-dimensional scattering needs component equations',P('In a two-dimensional collision, apply momentum to each axis. A single signed 1D equation cannot represent unknown directions. This lesson’s numeric collision model remains one-dimensional.'));
A(3,'Experimental energy losses need uncertainties',P('Compare the observed difference with measurement uncertainties before making a precise claim about elasticity. Velocity errors can strongly affect v² and therefore energy.'));
A(3,'Be clear about the collision interval',P('If carts roll on a rough track for a long time before velocities are recorded, friction can act outside the collision itself. Measure or infer velocities immediately before and after contact for the intended comparison.'));
A(3,'Not every algebraic solution is the interacting event',P('Conservation equations can include a no-change solution mathematically. Use the stated occurrence of collision and separation to select the physically relevant event.'));
A(3,'Your elasticity reference',E('Keep signs in p; square in Eₖ; use a second condition for two unknown final velocities')+P('For ideal elasticity, verify both conservation statements. Do not infer kinetic-energy conservation from momentum agreement alone.'));
s.mc('A collision that rebounds is necessarily elastic…',['true','false','only if both objects are visible'],1,'A rebound may still lose kinetic energy.');s.mc('Two unknown final 1D velocities require…',['momentum alone','another independent condition or measurement','equal speeds always'],1,'One equation cannot determine two unknowns generally.');s.mc('Equal masses in a 1D ideal elastic collision…',['exchange velocities','always stick','both stop'],0,'This is the physical interacting solution under the ideal assumptions.');s.mc('A heavy stationary target can make a light cart…',['rebound','always stop exactly','gain infinite speed'],0,'The solution can give a negative incident-cart final velocity.');s.mc('Kinetic energy is calculated from…',['signed momentum sums only','squared velocity magnitudes','the sign of displacement only'],1,'Each ½mv² contribution is nonnegative.');s.mc('Momentum agreement alone proves elasticity…',['true','false','only for head-on motion'],1,'Check total kinetic energy separately.');s.finish();
}
// Recoil and separation, including initially moving systems and experimental interpretation.
{
const s=make('y11-collisions-focus-3','y11-collisions','Recoil and explosions: frames, fragments and evidence','Recoil & experiments','Account for every fragment, compare initially resting and moving systems, and evaluate measurements.'),A=s.add;
A(0,'Internal energy can become motion',recoilDiagram()+P('A spring release, push or explosion can increase kinetic energy while conserving total system momentum if external impulse is negligible. The energy comes from a stored form.'));
A(0,'Initially at rest fixes total momentum to zero',E('0 = m₁v₁ + m₂v₂')+P('Equal and opposite momenta do not require equal speeds. The masses decide the speed ratio.'));
A(0,'A moving system starts with nonzero momentum',E('ptotal initial = (m₁ + m₂)U')+P('Both future fragments share the initial combined velocity before separation. Do not replace this total by zero merely because a push occurs internally.'));
A(0,'Include every relevant fragment',P('If a fragment is omitted, the visible remaining objects can appear to violate momentum conservation. The system definition determines which momentum terms belong in the calculation.'));
A(0,'Use one observer frame',P('Before and after velocities must belong to the same reference frame. A quoted velocity relative to the parent object must be converted or interpreted before combining it with ground-frame values.'));
A(0,'Internal forces are equal and opposite',P('Their impulses cancel for the whole included system. Each object individually gains momentum and accelerates according to its own mass. The total cancellation does not mean no motion develops.'));
A(0,'The event interval matters',P('A large external friction or gravitational impulse over a long observation period may change total momentum. A short horizontal release on a low-friction track can justify neglecting that contribution.'));
A(1,'Solve the stationary recoil equation',E('v₂ = −m₁v₁/m₂')+P('The minus sign encodes the opposite direction for positive masses. State the axis so “negative” has a physical meaning.'));
A(1,'Solve for a recoil speed ratio',E('|v₁|/|v₂| = m₂/m₁')+P('The lighter fragment moves faster in the two-fragment rest-system model. A speed ratio alone does not identify the stored energy released.'));
A(1,'The moving-system equation',E('(m₁ + m₂)U = m₁v₁ + m₂v₂')+P('This equation can yield both fragments moving forwards. Recoil is relative motion between parts; it does not require one fragment to move backwards relative to the ground.'));
A(1,'Calculate kinetic-energy gain separately',E('ΔEₖ = Σ½mvfinal² − ½(m₁ + m₂)U²')+P('A positive gain is supplied by internal stored energy in the ideal isolated event. Momentum conservation does not predict its magnitude without enough velocity information.'));
A(1,'Use measured velocities to evaluate conservation',E('Residual = pafter − pbefore')+P('Calculate the signed residual with units. Interpret it using uncertainty and possible external impulse, not just whether a rounded number equals zero.'));
A(1,'Choosing experimental measurements',P('Measure masses and velocities near the release event, repeat trials and control the track or setup. Position change divided by a long time may not represent the instantaneous velocity needed.'));
A(1,'Separate systematic and random effects',P('A tilted track supplies an external force; repeated trials on it do not make the system isolated. Timing scatter affects precision. Control the slope and analyse uncertainty separately.'));
A(2,'Worked explosion from rest',P('A 5.00 kg object at rest separates into a 2.00 kg fragment at +6.00 m/s and a 3.00 kg fragment with unknown velocity.')+recoilDiagram()+E('0 = 2.00(6.00) + 3.00v'),'worked');
A(2,'Worked explosion: solve direction',E('v = −12.0/3.00 = −4.00 m/s')+P('The heavier fragment moves left more slowly. The momenta are +12.0 and −12.0 kg·m/s.'),'worked');
A(2,'Worked explosion: energy released into motion',E('Eₖ after = ½(2.00)(6.00)² + ½(3.00)(4.00)²<br>= 36.0 + 24.0 = 60.0 J')+P('Initial kinetic energy was zero, so at least 60.0 J of internal energy has become macroscopic kinetic energy in the ideal budget.'),'worked');
A(2,'Worked moving release: retain the initial momentum',movingReleaseDiagram()+P('A 3.00 kg object moves at +2.00 m/s and separates into 1.00 kg and 2.00 kg parts. The 1.00 kg part has final velocity +5.00 m/s.')+E('3.00(2.00) = 1.00(5.00) + 2.00v<br>v = +0.500 m/s'),'worked');
A(2,'Worked moving release: interpret the directions',P('Both fragments move right relative to the ground, but the first outruns the second. In the parent’s original coasting frame their velocities are +3.00 and −1.50 m/s, giving cancelling relative-frame momenta. This is a low-speed frame comparison.')+E('1.00(3.00) + 2.00(−1.50) = 0'),'worked');
A(2,'Worked moving release: energy gain',energyBars('Moving release: kinetic energy increases',[['Before',6],['After',12.75],['Gain',6.75]])+E('Eₖ before = ½(3.00)(2.00)² = 6.00 J<br>Eₖ after = ½(1.00)(5.00)² + ½(2.00)(0.500)² = 12.75 J<br>Gain = 6.75 J')+P('Energy gain is frame-consistent here when both states are compared in the same ground frame.'),'worked');
A(2,'Worked measured residual',P('Two fragments have masses 0.500 and 0.750 kg and measured velocities +0.60 and −0.38 m/s after a release from rest.')+E('pafter = 0.500(0.60) + 0.750(−0.38) = +0.015 kg·m/s')+P('A small residual is evidence to analyse, not proof by itself of a new law failure. Estimate velocity/mass uncertainties and any external impulse.'),'worked');
A(3,'Guided: heavier fragment recoil',number('recoil-v','From rest, 1 kg moves at +8 m/s and a 4 kg partner recoils. Find its velocity.',-2,'m/s','0 = 1(8) + 4v → v = −2 m/s.',.01),'practice');
A(3,'Guided: an initially moving object',number('moving-v','A 4 kg system initially at +3 m/s separates into 1 kg at +6 m/s and 3 kg. Find the second velocity.',2,'m/s','4(3) = 1(6) + 3v gives v = +2 m/s.',.01),'practice');
A(3,'Guided: what zero momentum permits',check('zero-p','A two-fragment system has zero momentum but is moving. Its kinetic energy…',['must be zero','can be positive','must be negative'],1,['Opposite momenta can cancel while energy contributions add.','Correct: ½mv² is nonnegative for each moving part.','Kinetic energy cannot be negative.']),'practice');
const q1={q:'A 6.00 kg object at rest separates into 2.00 kg at +9.00 m/s and 4.00 kg with unknown velocity. Calculate the other velocity and total final kinetic energy.',points:['Initial momentum is zero: 0 = 2.00(9.00) + 4.00v.','Other velocity v = −4.50 m/s.','First fragment kinetic energy = ½ × 2.00 × 9.00² = 81.0 J.','Second fragment kinetic energy = ½ × 4.00 × 4.50² = 40.5 J.','Total final kinetic energy = 121.5 J, supplied from internal stored energy in the ideal release.']};
const q2={q:'A 5.00 kg object moves at +4.00 m/s before separating into a 2.00 kg part at +7.00 m/s and a 3.00 kg part. Find the second velocity, then explain two reasons experimental momentum measurements might give a small nonzero residual.',points:['Initial momentum = 5.00 × 4.00 = 20.0 kg·m/s.','20.0 = 2.00(7.00) + 3.00v gives v = +2.00 m/s.','Both ground-frame velocities are positive; internal separation need not send a fragment backwards in that frame.','A non-negligible external impulse, such as friction or a tilted track, can change system momentum.','Measurement uncertainty or recording velocities too long before/after release can also create an apparent residual.']};s.practice=[q1,q2];
A(3,'Independent: a release from rest',practice(q1),'practice');A(3,'Independent: motion and experimental evidence',practice(q2),'practice');
A(3,'A larger mass does not imply larger momentum always',P('Momentum is the product of mass and signed velocity. In a two-part release from rest, the momentum magnitudes match regardless of different masses, so the lighter part must have the larger speed.'));
A(3,'External versus internal energy input',P('A person pushing two objects from outside the chosen system can supply external impulse as well as energy. An internal spring release in an included system can supply energy without changing total momentum under the ideal conditions.'));
A(3,'Explosion is a description of a rapid energy release',P('The physics model can be demonstrated with a safe spring-loaded cart separation. These lessons analyse momentum and energy; they do not require dangerous explosive materials.'));
A(3,'Missing fragments change the accounting',P('If an event makes three fragments, include all three momentum terms. The two-fragment equation cannot determine the omitted momentum unless extra data are available.'));
A(3,'When a rocket is the chosen system',P('Exhaust leaving the rocket means a rocket-only system has changing included mass and momentum flow. For simple finite before/after questions, include rocket plus the specified expelled material and use the stated velocities in one frame.'));
A(3,'Your recoil reference',E('Choose included parts → state initial total momentum → keep one frame → solve signed velocities → check energy separately')+P('For experiments, quantify residuals and discuss uncertainty and external impulse rather than assuming exact agreement.'));
s.mc('From rest, two fragments have…',['equal-and-opposite momenta','equal speeds always','zero individual kinetic energies'],0,'Their total momentum is zero.');s.mc('Both fragments moving forwards after separation can occur when…',['the initial system was moving','momentum is impossible to conserve','both masses vanish'],0,'Initial nonzero momentum can persist with positive final velocities.');s.mc('Kinetic-energy gain can come from…',['internal stored energy','destroyed momentum','negative mass'],0,'A release converts internal energy to motion.');s.mc('Before/after velocities must use…',['one reference frame','different frames to simplify signs','only absolute speeds'],0,'Mixing frames makes the momentum equation inconsistent.');s.mc('Repeats alone remove an external track slope…',['true','false','only for equal masses'],1,'The systematic external force remains.');s.mc('A small measured momentum residual should be…',['analysed with uncertainty and external impulse','ignored always','called proof of conservation failure immediately'],0,'Interpret the experimental evidence and limitations.');s.finish();
}
function forceDistance(){return svg('Force-displacement graph rising linearly from zero to forty newtons over four metres; triangular area is work',arrow(100,320,690,320,'#0b8774')+arrow(100,320,100,45,'#2a6bb2')+'<path d="M100 320L580 80V320Z" fill="#e6f2e9" stroke="#c87518" stroke-width="4"/>'+text(110,35,'force parallel to displacement (N)')+text(75,86,'40','#18374d','end')+text(100,365,'0','#18374d','middle')+text(580,365,'4.00','#18374d','middle')+text(420,410,'displacement (m)')+text(145,455,'Area = ½ × 4.00 m × 40.0 N = 80.0 J'),495);}
function liftEnergy(){return svg('Load lifted upward with labelled vertical displacement and gravitational energy increase','<rect x="260" y="250" width="120" height="70" fill="#dcebf3" stroke="#18374d"/><rect x="260" y="85" width="120" height="70" fill="#e6f2e9" stroke="#18374d" stroke-dasharray="6 6"/>'+arrow(200,285,200,115,'#0b8774')+arrow(320,250,320,175,'#2a6bb2')+text(100,45,'Motor raises the load at constant speed')+text(95,205,'height H')+text(395,180,'motor force up')+text(395,295,'mass m')+text(100,395,'Useful energy gain = mgH')+text(100,440,'Useful power = mgH / total lifting time.'),480);}
// Work and kinetic energy: direction, net work and variable-force area.
{
const s=make('y11-work-energy-power-focus-1','y11-work-energy-power','Work and speed: force angles and variable-force graphs','Work & kinetic energy','Calculate individual and net work, then use the kinetic-energy change.'),A=s.add;
A(0,'A force can act without doing work',P('Holding a box stationary involves force but no displacement of the box, so the simple mechanical work on it is zero. A person or motor can still use energy internally; the system matters.'));
A(0,'Work requires displacement in a force direction',E('W = Fparallel s')+P('Only the force component along the displacement contributes. An object’s travelled path and the direction of the force must be interpreted before multiplying magnitudes.'));
A(0,'Identify the force doing the work',P('Work from a push is one force’s contribution. The net work is the sum of all relevant force contributions on the object and equals its kinetic-energy change.'));
A(0,'Positive work can increase kinetic energy',P('A forward force on a forward-moving object does positive work. A backward force such as opposing friction does negative work over the forward displacement.'));
A(0,'A perpendicular force does zero work here',P('For horizontal displacement on a level floor, weight and the vertical normal do no work. They can still matter to the contact model and friction, so zero work does not mean the forces are absent.'));
A(0,'Kinetic energy depends on speed, not direction sign',E('Eₖ = ½mv²')+P('An object at −5 m/s has the same kinetic energy as the same object at +5 m/s. Momentum distinguishes those directions; kinetic energy does not.'));
A(0,'A force graph needs displacement on its horizontal axis',forceDistance()+P('A force-time graph’s area gives impulse instead. The axes and units decide whether a shaded area represents work or momentum change.'));
A(1,'Resolve the force along displacement',E('Fparallel = F cosθ<br>W = Fs cosθ')+P('θ is between force and displacement. Draw both arrows from a common point to interpret the angle. If the angle is measured from a different axis, identify the correct component.'));
A(1,'The angle sets the work sign',E('θ = 0° → W = +Fs<br>θ = 90° → W = 0<br>θ = 180° → W = −Fs')+P('A right-angle force does not transfer kinetic energy through this displacement in the simple model. An opposite-directed force can remove kinetic energy.'));
A(1,'Net work-energy theorem',E('ΣWforces = ΔEₖ = Eₖ final − Eₖ initial')+P('Keep the initial kinetic energy when the object is already moving. Starting from rest is a specific condition, not a default.'));
A(1,'Recover speed by undoing a square',E('v = √[2(Eₖ initial + Wnet)/m]')+P('This gives speed magnitude. Direction still needs the motion scenario. A negative predicted energy means the proposed endpoint cannot be reached under that budget.'));
A(1,'Constant-force area is rectangular',E('W = Fparallel Δx')+P('For a signed force-displacement graph with a constant value, its area is force times displacement interval. State whether the displayed force is an individual or net force.'));
A(1,'Variable-force area can still give work',E('W = area under Fparallel(x)')+P('A linearly varying force can have a triangular or trapezium area. Work-energy does not require constant acceleration, whereas the standard constant-a motion equations do.'));
A(1,'Avoid double-counting a transfer',P('When using net work on an object, include gravity work if gravity contributes. When using an object-plus-Earth energy budget with gravitational potential energy, do not also add the same gravity transfer a second time.'));
A(2,'Worked horizontal push: individual work',P('A 30.0 N rightward push acts on a 2.00 kg object moving 5.00 m right. Opposing friction is 8.00 N.')+E('Wpush = +30.0(5.00) = +150 J<br>Wfriction = −8.00(5.00) = −40.0 J'),'worked');
A(2,'Worked horizontal push: net work',E('Wnet = 150 − 40.0 = +110 J')+P('Vertical weight and normal do zero work over the horizontal displacement. The positive net work means the object gains kinetic energy.'),'worked');
A(2,'Worked horizontal push: initial motion matters',energyBars('Net-work budget',[['Initial Eₖ',9],['Net work',110],['Final Eₖ',119]])+P('Initial speed is 3.00 m/s.')+E('Eₖ initial = ½(2.00)(3.00)² = 9.00 J<br>Eₖ final = 9.00 + 110 = 119 J<br>v = √[2(119)/2.00] = 10.9 m/s')+P('Using Wnet as the whole final energy would omit the energy it already had.'),'worked');
A(2,'Worked angled pull',workAngle()+P('A 40.0 N force at 60.0° to a horizontal 3.00 m displacement pulls a box.')+E('Fparallel = 40.0cos60° = 20.0 N<br>Wpull = 20.0(3.00) = 60.0 J')+P('The perpendicular component contributes no work along this horizontal displacement. Other forces may still make net work differ from this 60.0 J.'),'worked');
A(2,'Worked opposing force',P('A force of 15.0 N acts opposite a 4.00 m forward displacement on an object with initial kinetic energy 100 J.')+E('W = −15.0(4.00) = −60.0 J<br>Eₖ final = 100 − 60.0 = 40.0 J')+P('Negative work reduces kinetic energy; it does not make the kinetic energy itself negative.'),'worked');
A(2,'Worked variable-force graph',forceDistance()+E('Wnet = ½(4.00)(40.0) = 80.0 J')+P('If the graph shows the net parallel force on a 2.00 kg object initially at rest, Eₖ final = 80.0 J and speed = √80.0 = 8.94 m/s.'),'worked');
A(2,'Worked feasibility: the object stops before the proposed point',P('An object has 30.0 J initial kinetic energy and experiences constant 10.0 N opposing force. Can it travel 5.00 m before stopping?')+E('Required transfer = 50.0 J &gt; 30.0 J<br>sstop = 30.0/10.0 = 3.00 m')+P('It stops earlier. An energy result of −20.0 J at 5.00 m is evidence that the assumed event is unreachable, not permission to take a square root of its magnitude.'),'worked');
A(3,'Explore force angle and work','<div class="pp-sim" data-work-lab><div class="pp-sim-controls"><label>Force (N)<input data-wf type="range" min="10" max="60" step="5" value="40"><output data-wfl></output></label><label>Angle to displacement (degrees)<input data-wa type="range" min="0" max="180" step="15" value="60"><output data-wal></output></label></div><div class="pp-sim-readout pp-scenario-readout" aria-live="polite"></div><p>Displacement is 3.00 m right. This reports the selected force’s work, not automatically net work.</p></div>','interactive');
s.wire=root=>root.querySelectorAll('[data-work-lab]').forEach(el=>{function update(){const F=+el.querySelector('[data-wf]').value,a=+el.querySelector('[data-wa]').value,w=3*F*Math.cos(a*Math.PI/180);el.querySelector('[data-wfl]').textContent=F+' N';el.querySelector('[data-wal]').textContent=a+'°';el.querySelector('.pp-sim-readout').textContent='Parallel component = '+(F*Math.cos(a*Math.PI/180)).toFixed(2)+' N; work = '+w.toFixed(2)+' J.';}el.querySelectorAll('input').forEach(i=>i.oninput=update);update();});
A(3,'Guided: a right-angle force',number('work-right','Work from a 50 N perpendicular force over 2 m displacement',0,'J','W = Fs cos90° = 0.',.01),'practice');
A(3,'Guided: kinetic energy at a signed velocity',number('work-kinetic','Kinetic energy of 3.00 kg at velocity −4.00 m/s',24,'J','Eₖ = ½ × 3.00 × (−4.00)² = 24.0 J.',.01),'practice');
const q1={q:'A 5.00 kg crate initially moves at 2.00 m/s. A horizontal 25.0 N push and 10.0 N opposing friction act over 4.00 m. Find push work, friction work, net work and final speed.',points:['Push work = +25.0 × 4.00 = +100 J.','Friction work = −10.0 × 4.00 = −40.0 J; net work = +60.0 J.','Initial kinetic energy = ½ × 5.00 × 2.00² = 10.0 J.','Final kinetic energy = 70.0 J.','Speed = √(2 × 70.0/5.00) = 5.29 m/s.']};
const q2={q:'A net parallel force increases linearly from 10.0 N to 30.0 N over 6.00 m. It acts on a 4.00 kg object initially at rest. Calculate work and final speed, and state why a constant-acceleration displacement equation is not directly appropriate.',points:['Work is trapezium area = ½(10.0 + 30.0) × 6.00 = 120 J.','Net work equals kinetic-energy gain, so final Eₖ = 120 J.','Final speed = √(2 × 120/4.00) = 7.75 m/s.','The force and therefore acceleration vary with position; constant-a equations cannot be assumed over the whole interval.']};s.practice=[q1,q2];
A(3,'Independent: separate works and initial energy',practice(q1),'practice');A(3,'Independent: a variable-force area',practice(q2),'practice');
A(3,'Work is signed but energy stores remain physically constrained',P('An object can lose 20 J of kinetic energy through negative work. It must initially have at least 20 J to complete that proposed interval without additional input.'));
A(3,'Force-distance units check the calculation',E('N·m = kg·m²/s² = J')+P('Force-time area has N·s units instead, corresponding to impulse. Similar triangle shapes can represent different physics because their axes differ.'));
A(3,'An applied-force graph may need other work terms',P('If a graph shows only motor force and friction also acts, subtract the friction work before assigning the result to ΔEₖ. Read whether the graph is applied force or net force.'));
A(3,'A turn in the path changes the force angle',P('For a changing path, a force’s angle relative to each displacement segment can vary. Divide into stated segments with suitable directions rather than multiplying total distance by one unrelated angle.'));
A(3,'The system choice links work and potential energy',P('An object falling under gravity can be solved by net gravity work on the object or by gravitational-potential-energy decrease in an object-plus-Earth system. Use one consistent accounting route.'));
A(3,'Your work reference',E('Identify force and displacement → resolve along path → sum works → add initial Eₖ → solve speed')+P('For a force-displacement graph use signed area and check whether it is a net-force graph.'));
s.mc('Work from a force perpendicular to displacement is…',['Fs','zero','always negative'],1,'Its parallel component is zero.');s.mc('Net work equals…',['final kinetic energy always','kinetic-energy change','momentum change'],1,'Initial kinetic energy must be accounted for.');s.mc('The area under force versus displacement has units…',['J','N·s','W'],0,'N·m is joules.');s.mc('An object at negative velocity has kinetic energy…',['negative','nonnegative','zero always'],1,'Velocity is squared.');s.mc('A varying net force implies acceleration…',['is generally varying','must be zero','must be constant'],0,'For fixed mass, a = Fnet/m.');s.mc('A negative predicted final kinetic energy means…',['the proposed endpoint is unreachable under the budget','use its absolute value','mass is negative'],0,'The object stops earlier or needs more input.');s.finish();
}
// Power and efficiency: average/instantaneous rates, output boundaries and unit conversions.
{
const s=make('y11-work-energy-power-focus-3','y11-work-energy-power','Power and efficiency: motors, timing and output budgets','Power & efficiency','Calculate energy-transfer rates, useful output and required input in different operating scenarios.'),A=s.add;
A(0,'Equal work can be delivered at different rates',liftEnergy()+P('Two motors lift the same load through the same height. The useful energy gain can be the same, but a shorter lift time requires greater average useful power.'));
A(0,'A watt is a rate unit',E('1 W = 1 J/s')+P('A 500 W input means 500 J of energy crosses the stated input boundary each second at that operating rate. It is not 500 J total unless the duration is one second.'));
A(0,'Useful output needs a definition',P('For lifting, useful output may be gravitational potential-energy gain. For a heater, useful output may be energy absorbed by a particular sample. A device can have several outputs; identify which the stated efficiency counts.'));
A(0,'Input and output cannot be silently swapped',E('η = useful output / input')+P('An 80% efficient motor converts 0.80 of the specified input into the specified useful output. The rest goes into other forms or destinations.'));
A(0,'Average power is not necessarily peak power',P('Average power divides total energy by total time. A varying device can have larger momentary peaks. An average energy/time calculation does not reveal the exact time profile.'));
A(0,'Mechanical output can be zero while input is nonzero',P('A motor holding a stationary load may supply force with no load displacement. Its useful mechanical lifting power is zero, while real internal heating can still require input.'));
A(0,'Choose consistent time units',P('Convert minutes to seconds for watts and joules. For kWh, use kilowatts multiplied by hours. Mixing watts with hours and calling the result joules loses a factor of 3600.'));
A(1,'Average power relationship',E('Paverage = ΔE/Δt = W/Δt')+P('Use the energy or work associated with the stated boundary. For useful output power, divide useful output by time, not total input unless efficiency is unity.'));
A(1,'Recover energy or time',E('E = PΔt; Δt = E/P')+P('These products assume constant P, or use average P over the interval. A rated power may be a maximum or nominal value rather than the actual average; read the question’s operating assumption.'));
A(1,'Required input for a known useful output',E('Einput = Euseful/η<br>Pinput = Puseful/η')+P('Input must exceed useful output when 0 &lt; η &lt; 1. Multiplying useful energy by η again would incorrectly reduce the required input.'));
A(1,'Constant-speed lifting',E('Euseful = mgH<br>Puseful = mgH/t')+P('The load can have zero acceleration but still gain gravitational potential energy. Motor force balances weight while its positive work offsets gravity’s negative work on the load.'));
A(1,'Mechanical force-rate relation',E('P = Fparallel v')+P('This follows from work per time: Fs/t and v = s/t. For varying velocity it describes the instantaneous mechanical rate under the stated force relation, not automatically a whole-journey average.'));
A(1,'Kilowatt-hours are energy',E('1 kWh = 1000 W × 3600 s = 3.60 × 10⁶ J')+P('kWh is not kW per hour. It is power multiplied by duration, so it measures energy.'));
A(1,'Two consecutive efficiencies multiply',E('ηoverall = η₁η₂')+P('If one stage’s output becomes the next stage’s input, multiply the fractions. Adding the percentages would incorrectly imply an output greater than its input in many cases.'));
A(2,'Worked motor: useful energy and power',P('A motor raises 80.0 kg through 5.00 m in 10.0 s at constant speed. Efficiency is 75.0%.')+liftEnergy()+E('Euseful = 80.0(9.80)(5.00) = 3920 J'),'worked');
A(2,'Worked motor: required input',E('Puseful = 3920/10.0 = 392 W<br>Pinput = 392/0.750 = 523 W')+P('The useful output is only part of the input. Both powers refer to the same ten-second interval.'),'worked');
A(2,'Worked motor: input energy and other transfers',energyBars('Motor energy input and output',[['Input',3920/.75],['Useful',3920],['Other',3920/.75-3920]])+E('Einput = 3920/0.750 = 5226.67… J<br>Eother = Einput − Euseful = 1306.67… J')+P('The other energy has not vanished; it may heat the motor or surroundings. The exact destinations require the device model.'),'worked');
A(2,'Worked force and speed',P('A drive supplies a forward mechanical force of 200 N while its output point moves at 3.00 m/s.')+E('Pmechanical = 200(3.00) = 600 W')+P('At 4.00 m/s with the same force the rate would be 800 W. If a fixed power limit applies, the force may instead need to decrease as speed rises.'),'worked');
A(2,'Worked timed energy input',P('A heater operates at a stated constant 1.20 kW for 5.00 min.')+E('Einput = 1200(300) = 360 000 J = 360 kJ<br>Equivalent = 1.20 × (5.00/60.0) = 0.100 kWh')+P('The two energy units describe the same amount. Heater efficiency would determine which fraction reaches the specified sample.'),'worked');
A(2,'Worked output and time',P('A device must deliver 18.0 kJ useful energy with 500 W input and 60.0% efficiency.')+E('Puseful = 0.600(500) = 300 W<br>t = 18 000/300 = 60.0 s')+P('Use useful power for useful energy, or divide useful energy by efficiency before using input power. Both routes agree.'),'worked');
A(2,'Worked two stages',P('A power system receives 2000 J. Its first conversion is 40.0% efficient and its second 80.0% efficient.')+E('Output stage 1 = 800 J<br>Final useful output = 0.800(800) = 640 J<br>Overall efficiency = 0.400(0.800) = 32.0%')+P('The stage-two input is only 800 J, not the original 2000 J.'),'worked');
A(3,'Explore a lifting budget','<div class="pp-sim" data-power-lab><div class="pp-sim-controls"><label>Load mass (kg)<input data-pm type="range" min="10" max="100" step="10" value="80"><output data-pml></output></label><label>Lift time (s)<input data-pt type="range" min="2" max="20" step="2" value="10"><output data-ptl></output></label><label>Efficiency (%)<input data-pe type="range" min="40" max="100" step="5" value="75"><output data-pel></output></label></div><div class="pp-sim-readout pp-scenario-readout" aria-live="polite"></div><p>Height is 5.00 m; constant lifting speed; stated efficiency refers to gravitational-energy output.</p></div>','interactive');
s.wire=root=>root.querySelectorAll('[data-power-lab]').forEach(el=>{function update(){const m=+el.querySelector('[data-pm]').value,t=+el.querySelector('[data-pt]').value,e=+el.querySelector('[data-pe]').value/100,E=m*9.8*5;el.querySelector('[data-pml]').textContent=m+' kg';el.querySelector('[data-ptl]').textContent=t+' s';el.querySelector('[data-pel]').textContent=(e*100).toFixed(0)+'%';el.querySelector('.pp-sim-readout').textContent='Useful energy = '+E.toFixed(0)+' J; useful average power = '+(E/t).toFixed(1)+' W; input average power = '+(E/(t*e)).toFixed(1)+' W.';}el.querySelectorAll('input').forEach(i=>i.oninput=update);update();});
A(3,'Guided: an input power',number('p-input','Useful output is 900 W and efficiency is 75%. Find input power.',1200,'W','Pinput = 900/0.75 = 1200 W.',.1),'practice');
A(3,'Guided: an energy unit',number('p-kwh','Convert 0.250 kWh to megajoules.',.9,'MJ','0.250 × 3.60 MJ = 0.900 MJ.',.001),'practice');
const q1={q:'A 120 kg load rises through 4.00 m in 8.00 s at constant speed with motor efficiency 80.0%. Find useful work, useful average power and input average power.',points:['Useful work = 120 × 9.80 × 4.00 = 4704 J.','Useful average power = 4704/8.00 = 588 W.','Input average power = 588/0.800 = 735 W.','Constant velocity makes net force zero on the load, not motor work or useful lifting power zero.']};
const q2={q:'A device runs at a stated constant 2.00 kW input for 3.00 min. Its useful-output efficiency is 65.0%. Calculate input energy in J and kWh, useful energy and useful average power.',points:['Time = 180 s; input energy = 2000 × 180 = 360 000 J.','Input energy = 2.00 × 3.00/60.0 = 0.100 kWh.','Useful energy = 0.650 × 360 000 = 234 000 J.','Useful average power = 234 000/180 = 1300 W.','The remaining 126 000 J transfers to other forms or destinations under the stated output definition.']};s.practice=[q1,q2];
A(3,'Independent: lifting and input power',practice(q1),'practice');A(3,'Independent: timed energy and efficiency',practice(q2),'practice');
A(3,'Changing time versus changing height',energyBars('Same lift, different useful average power',[['10 s lift',392],['5 s lift',784]],'W')+P('For fixed mass and height, useful work is fixed while average power varies inversely with time. Doubling height at fixed time and mass doubles useful work and average power. State the controlled variables.'));
A(3,'A rated power is not always the operating power',P('An actual device may cycle on and off or vary its input. Use a supplied duty cycle or measured energy when given. Do not assume a nameplate maximum applies continuously unless the problem says so.'));
A(3,'Duty-cycle average',E('Paverage = Pon × fraction of time on when off-power is zero')+P('A 1000 W device on for 30% of a long interval has 300 W average input in that simplified model. A nonzero standby power would add another term.'));
A(3,'A power limit can change the force available',E('At constant output P: Fparallel = P/v')+P('This relation applies to a moving output point with v nonzero. Starting dynamics require the device’s actual force and operating model; it is not valid to infer an infinite real force at v = 0.'));
A(3,'Define efficiency before comparing devices',P('A machine providing both useful motion and useful heating may be assessed with a different useful-output boundary from one where the heat is unwanted. State the counted outputs rather than comparing unexplained percentages.'));
A(3,'Your power reference',E('Identify input/output → choose E and time → convert units → apply η once → check rate versus amount')+P('Use kWh for energy, watts for rates, and distinguish average from instantaneous or peak power.'));
s.mc('kWh measures…',['energy','power change per hour','current'],0,'Power multiplied by time gives energy.');s.mc('Input power needed for useful P at efficiency η is…',['P/η','Pη','η/P'],0,'Useful output is a fraction of input.');s.mc('Same lift done in half the time requires useful average power…',['half as large','twice as large','unchanged'],1,'Work is fixed; divide by half the time.');s.mc('Two serial efficiencies 50% and 80% give overall…',['130%','40%','65%'],1,'Multiply fractions 0.50 × 0.80.');s.mc('Holding a load stationary implies mechanical lifting power…',['zero for the load displacement','always equal to input','infinite'],0,'No load displacement means no mechanical work on that load.');s.mc('Average power alone determines the peak power…',['always','not generally','only when input is in watts'],1,'A time-varying power profile can have larger peaks.');s.finish();
}
})();
